read_jd.code:
(function(){
    var jdText = '';
    var descEl = document.querySelector(__SEL_BODY__);
    if (descEl) jdText = descEl.innerText.trim();

    var titleEl = document.querySelector(__SEL_TITLE__);
    var jobTitle = titleEl ? titleEl.textContent.trim() : '';

    var salaryEl = document.querySelector(__SEL_SALARY__);
    var salary = salaryEl ? salaryEl.textContent.trim() : '';

    var city = '', experience = '', degree = '';
    var tagItems = document.querySelectorAll(__SEL_TAGS__);
    for (var i = 0; i < tagItems.length; i++) {
        var text = tagItems[i].textContent.trim();
        var link = tagItems[i].querySelector('a');
        if (link) city = link.textContent.trim();
        else if (text.indexOf('年') >= 0 || text.indexOf('经验') >= 0) experience = text;
        else if (text.indexOf('本科') >= 0 || text.indexOf('大专') >= 0 ||
                 text.indexOf('硕士') >= 0 || text.indexOf('学历') >= 0 ||
                 text.indexOf('不限') >= 0) degree = text;
    }

    var company = '';
    var bossName = '', bossTitle = '';
    var bossInfo = document.querySelector(__SEL_BOSS__);
    if (bossInfo) {
        var parts = (bossInfo.innerText || '').split('\n');
        if (parts.length > 0) bossName = parts[0].trim();
        if (parts.length > 2) bossTitle = parts[2].trim();
    }

    var panelEl = document.querySelector(__SEL_PANEL__);
    var fullText = panelEl ? panelEl.innerText.trim() : '';

    return JSON.stringify({
        jd_text: jdText, job_title: jobTitle, company: company,
        salary: salary, city: city, experience: experience, degree: degree,
        boss_name: bossName, boss_title: bossTitle, full_text: fullText
    });
})()

find_card.code:
(function(targetJid){
    var link = document.querySelector('a[href*="job_detail/' + targetJid + '"]');
    if (!link) {
        var allLinks = document.querySelectorAll(__SEL_CARD_LINK__);
        for (var i = 0; i < allLinks.length; i++) {
            if ((allLinks[i].getAttribute('href') || '').indexOf(targetJid) >= 0) {
                link = allLinks[i]; break;
            }
        }
    }
    if (!link) return JSON.stringify({found:false, detail:'no_link_match'});

    var card = link.closest(__SEL_CARD_CONTAINER__);
    if (!card) return JSON.stringify({found:false, detail:'no_card_container'});
    card.scrollIntoView({behavior:'smooth', block:'center'});

    var title = '';
    var titleEl = card.querySelector(__SEL_CARD_TITLE__);
    if (titleEl) title = titleEl.textContent.trim();
    return JSON.stringify({found:true, title:title});
})(__JID__)

