verify_panel.code:
(function(targetJid){
    var detailLinks = document.querySelectorAll(__SEL_CARD_LINK__);
    for (var j = 0; j < detailLinks.length; j++) {
        if ((detailLinks[j].getAttribute('href') || '').indexOf(targetJid) >= 0)
            return JSON.stringify({ok:true, method:'detail_link'});
    }
    var body = document.querySelector(__SEL_BODY_CONTAINER__);
    if (body && body.innerText.trim().length > 50)
        return JSON.stringify({ok:true, method:'body_populated'});
    var sec = document.querySelector(__SEL_SECTION__);
    if (sec && sec.innerText.trim().length > 50)
        return JSON.stringify({ok:true, method:'sec_populated'});
    return JSON.stringify({ok:false, method:'none'});
})(__JID__)

handle_popup.code:
(function(){
    // 20261113: 弹窗会叠加多层遮罩，命中即 return 只关一层，后续点击被残余遮罩拦截 →
    //        改为循环关闭，直到本轮扫不到可点按钮为止；容器类选择器自动下沉找按钮。
    var selectors = __POPUP_SELECTORS__;
    var texts = ['好', '确定', '我知道了', '知道了', '继续沟通', '关闭', '明白了', '下次再说'];
    var hits = [];
    var guard = 0;

    function visible(el) {
        if (!el) return false;
        var r = el.getBoundingClientRect();
        if (r.width <= 0 || r.height <= 0) return false;
        var s = window.getComputedStyle(el);
        return s.display !== 'none' && s.visibility !== 'hidden' && s.opacity !== '0';
    }
    function isBtn(el) {
        if (!el) return false;
        var tag = el.tagName;
        if (tag === 'BUTTON' || tag === 'A') return true;
        return /(^|\s)(btn|sure|confirm|ok)[\w-]*/i.test(el.className || '');
    }
    function buttonIn(root) {
        if (isBtn(root)) return root;
        var kids = root.querySelectorAll('button, a, .btn, .btn-sure, [class*="btn"], [class*="sure"], [class*="confirm"]');
        for (var i = 0; i < kids.length; i++) {
            if (visible(kids[i])) return kids[i];
        }
        return null;
    }
    function fire(el) {
        var r = el.getBoundingClientRect();
        var x = r.left + r.width / 2;
        var y = r.top + r.height / 2;
        ['mousedown', 'mouseup', 'click'].forEach(function (type) {
            el.dispatchEvent(new MouseEvent(type, {
                bubbles: true, cancelable: true, view: window, clientX: x, clientY: y
            }));
        });
    }

    while (guard++ < 8) {
        var target = null;
        var hit = '';

        for (var p = 0; p < selectors.length && !target; p++) {
            var nodes = document.querySelectorAll(selectors[p]);
            for (var n = 0; n < nodes.length; n++) {
                if (!visible(nodes[n])) continue;
                var cand = buttonIn(nodes[n]);
                if (cand) { target = cand; hit = selectors[p]; break; }
            }
        }

        if (!target) {
            // 文本兜底第一趟：只认叶子节点，避免点在弹窗容器上（容器 textContent 也可能是"好"）
            var pool = document.querySelectorAll('button, a, span, i, div');
            for (var k = 0; k < pool.length; k++) {
                var leaf = pool[k];
                if (leaf.children.length > 0) continue;
                var text = (leaf.textContent || '').trim();
                if (!text || text.length > 8) continue;
                if (texts.indexOf(text) >= 0 && visible(leaf)) { target = leaf; hit = 'text:' + text; break; }
            }
            // 第二趟：整块文案命中时，下沉取容器内部按钮
            if (!target) {
                for (var m = 0; m < pool.length; m++) {
                    var box = pool[m];
                    if (box.children.length === 0) continue;
                    var boxText = (box.textContent || '').trim();
                    if (!boxText || boxText.length > 8) continue;
                    if (texts.indexOf(boxText) < 0 || !visible(box)) continue;
                    var inner = buttonIn(box);
                    if (inner) { target = inner; hit = 'text-in:' + boxText; break; }
                }
            }
        }

        if (!target) break;
        try { fire(target); } catch (e) { break; }
        hits.push(hit);
    }

    return JSON.stringify({clicked: hits.length, hits: hits});
})()

